package main

import (
	"context"
	"fmt"
	"strings"

	"github.com/viant/jsonrpc"
	mcpschema "github.com/viant/mcp-protocol/schema"
	mcpproto "github.com/viant/mcp-protocol/server"
)

type largeResultOut struct {
	Body string `json:"body"`
}

// largeResultBody supplies genuine deterministic oversized tool data. The model
// response and continuation preview remain generated by the actual application.
func largeResultBody() string {
	var result strings.Builder
	result.Grow(131072)
	for chunk := 0; result.Len() < 131072; chunk++ {
		fmt.Fprintf(&result, "CHUNK-%04d LARGE_RESULT_SENTINEL %s\n", chunk, strings.Repeat("x", 48))
	}
	return result.String()
}

func (h *handler) registerLargeResult() error {
	return mcpproto.RegisterTool[*emptyIn, *largeResultOut](h.Registry, "large_result", "Returns an oversized deterministic result for continuation preview integration", func(_ context.Context, _ *emptyIn) (*mcpschema.CallToolResult, *jsonrpc.Error) {
		return success(&largeResultOut{Body: largeResultBody()})
	})
}
